import React, { useEffect } from 'react';
import { KeyboardDoubleArrowLeft, KeyboardDoubleArrowRight, KeyboardDoubleArrowUp, KeyboardDoubleArrowDown, ArrowBack, RestartAlt } from '@mui/icons-material';
import Button from '@mui/material/Button';
import Dialog from '@mui/material/Dialog';
import DialogTitle from '@mui/material/DialogTitle';
import DialogContent from '@mui/material/DialogContent';
import DialogActions from '@mui/material/DialogActions';
import { Box, Card, CardActions, CardContent, CardHeader, CardMedia, Divider, Typography } from '@mui/material';
import { useGlobalScores } from "../App";

const GameOver = ({ open=false,gameName, score, handleClose, handleRestart }) =>{
  const {setScore, getScoreByGame} = useGlobalScores();
  const [hiScore, setHiScore] = React.useState('Aucun');
  const doClose =(evt,reason)=>{
    if(window.gtag)
window.gtag('event', 'jeu_termine', { event_label: gameName, score: score });
    if(reason!='backdropClick')
     handleClose(evt);
  } 
  const doRestart=(evt)=>{
    handleRestart();
    doClose(evt);
  }
  useEffect(()=>{
    if(gameName!=null){
      const hiscores = getScoreByGame(gameName);
      if(hiscores!=null && hiscores.score!=null)
        setHiScore(hiscores.score);
      if(hiscores.score<score)
        setScore(gameName,score);
    }
  },[gameName, score]);
  return (
    <Dialog open={open} onClose={doClose}>
      <DialogTitle>Partie terminée</DialogTitle>
      <DialogContent>
        <Typography color="primary">Votre score : {score}</Typography>
        <Typography variant="caption" color="text.secondary">Hi-score actuel: {hiScore}</Typography>
      </DialogContent>
      <DialogActions>
        <Button onClick={handleClose}>Fermer</Button>
        <Button onClick={doRestart}>Recommencer</Button>
      </DialogActions>
    </Dialog>
  );
}


export const Score2048 = ({
  handleRestart,
  lastSwipe,
  score,
  gridSize,
  setGridSize,
}) => {
  const getArrowIcon = (dir) => {
    switch (dir) {
      case "left":
        return <KeyboardDoubleArrowLeft fontSize="large" color="primary" />;
      case "right":
        return <KeyboardDoubleArrowRight fontSize="large" color="primary" />;
      case "up":
        return <KeyboardDoubleArrowUp fontSize="large" color="primary" />;
      case "down":
        return <KeyboardDoubleArrowDown fontSize="large" color="primary" />;
      default:
        return null;
    }
  };

  return (
    <Card
      elevation={10}
      sx={{
        width: 260,
        borderRadius: 4,
        backdropFilter: "blur(6px)",
        background: "rgba(25,25,25,0.85)",
        color: "#f0f0f0",
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        p: 2,
        boxShadow: "0 0 20px #222",
      }}
    >
      <Typography
        variant="h4"
        sx={{
          fontWeight: "bold",
          color: "#ffcc00",
          textShadow: "0 0 12px #ffcc0044",
        }}
      >
        2048
      </Typography>

      <Typography
        variant="h6"
        sx={{
          mt: 1,
          color: "#fafafa",
          fontFamily: "monospace",
          backgroundColor: "#333",
          px: 2,
          py: 1,
          borderRadius: 2,
          boxShadow: "0 0 8px #000 inset",
        }}
      >
        Score : {score}
      </Typography>

      <Box sx={{ mt: 2, minHeight: 60 }}>{getArrowIcon(lastSwipe)}</Box>

      <Divider sx={{ my: 2, width: "80%", borderColor: "#555" }} />

      <Typography variant="subtitle2" sx={{ mb: 1, opacity: 0.8 }}>
        Taille de la grille
      </Typography>

      <Box sx={{ display: "flex", gap: 1, flexWrap: "wrap", justifyContent: "center" }}>
        {[3, 4, 6, 12].map((size) => (
          <Button
            key={size}
            variant={gridSize === size ? "contained" : "outlined"}
            color={gridSize === size ? "secondary" : "primary"}
            sx={{
              minWidth: 40,
              borderRadius: 2,
              transition: "all 0.3s ease",
              "&:hover": {
                transform: "scale(1.1)",
              },
            }}
            onClick={() => setGridSize(size)}
          >
            {size}
          </Button>
        ))}
      </Box>

      <Divider sx={{ my: 2, width: "80%", borderColor: "#555" }} />

      <Button
        variant="contained"
        color="error"
        startIcon={<RestartAlt />}
        onClick={handleRestart}
        sx={{
          borderRadius: 3,
          px: 3,
          mt: 1,
          transition: "all 0.3s ease",
          "&:hover": {
            backgroundColor: "#ff4444",
            transform: "scale(1.05)",
          },
        }}
      >
        Recommencer
      </Button>
    </Card>
  );
};

export default GameOver;